{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "config": {
    "kibana": {
      "hideWarnings": true
    },
    "text": {
      "fill": "#343741",
      "font": "Inter UI, -apple-system, BlinkMacSystemFont, Segoe UI, Helvetica, Arial, sans-serif",
      "fontSize": 13
    }
  },
  "data": [
    {
      "format": {
        "property": "aggregations.top.buckets"
      },
      "name": "top",
      "transform": [
        {
          "as": [
            "rank"
          ],
          "ops": [
            "row_number"
          ],
          "sort": {
            "field": "doc_count",
            "order": "descending"
          },
          "type": "window"
        }
      ],
      "url": {
        "body": {
          "aggs": {
            "top": {
              "terms": {
                "field": "agent.name",
                "size": 10
              }
            }
          },
          "query": {
            "bool": {
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "query_string": {
                    "analyze_wildcard": true,
                    "query": "rule.id:[132100 TO 132199] AND rule.id:/[0-9]{6}/"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "size": 0
        },
        "index": "wazuh-alerts-*"
      }
    }
  ],
  "marks": [
    {
      "encode": {
        "update": {
          "align": {
            "value": "right"
          },
          "baseline": {
            "value": "middle"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#006BB4"
          },
          "limit": {
            "signal": "labelW - 8"
          },
          "text": {
            "field": "key"
          },
          "tooltip": {
            "signal": "{'告警最多的代理程式': datum.key, '告警': format(datum.doc_count, ',')}"
          },
          "x": {
            "signal": "labelW - 8"
          },
          "y": {
            "signal": "34 + (datum.rank - 1) * barH + barH / 2"
          }
        }
      },
      "from": {
        "data": "top"
      },
      "name": "jtLabel",
      "type": "text"
    },
    {
      "encode": {
        "hover": {
          "fill": {
            "value": "#006BB4"
          }
        },
        "update": {
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#6092C0"
          },
          "height": {
            "signal": "barH * 0.64"
          },
          "tooltip": {
            "signal": "{'告警最多的代理程式': datum.key, '告警': format(datum.doc_count, ',')}"
          },
          "width": {
            "signal": "max(1, scale('len', datum.doc_count))"
          },
          "x": {
            "signal": "labelW"
          },
          "y": {
            "signal": "34 + (datum.rank - 1) * barH + barH * 0.18"
          }
        }
      },
      "from": {
        "data": "top"
      },
      "name": "jtBar",
      "type": "rect"
    },
    {
      "encode": {
        "update": {
          "baseline": {
            "value": "middle"
          },
          "fill": {
            "value": "#69707D"
          },
          "text": {
            "signal": "format(datum.doc_count, ',')"
          },
          "x": {
            "signal": "labelW + max(1, scale('len', datum.doc_count)) + 6"
          },
          "y": {
            "signal": "34 + (datum.rank - 1) * barH + barH / 2"
          }
        }
      },
      "from": {
        "data": "top"
      },
      "type": "text"
    }
  ],
  "padding": {
    "bottom": 8,
    "left": 8,
    "right": 8,
    "top": 8
  },
  "scales": [
    {
      "domain": {
        "data": "top",
        "field": "doc_count"
      },
      "name": "len",
      "nice": false,
      "range": [
        0,
        {
          "signal": "width - labelW - 70"
        }
      ],
      "type": "linear",
      "zero": true
    }
  ],
  "signals": [
    {
      "name": "jtPick",
      "on": [
        {
          "events": "@jtBar:click, @jtLabel:click, @jtSlice:click, @jtKey:click",
          "update": "opensearchDashboardsAddFilter({'match_phrase': {\"agent.name\": datum.key}}, \"wazuh-alerts-*\", \"agent.name\" + ': ' + datum.key)"
        }
      ],
      "value": null
    },
    {
      "name": "labelW",
      "update": "min(220, width * 0.3)"
    },
    {
      "name": "barH",
      "update": "min(34, (height - 34) / max(1, length(data('top'))))"
    }
  ]
}"},"title":"jt-vc-portal · 告警最多的代理程式","type":"vega"}

